units.source:
export function createDeferred<T>(): Deferred<T> {
  let resolve!: (value: T | PromiseLike<T>) => void
  let reject!: (reason?: Error | unknown) => void
  let isPending = true

  const promise = new Promise<T>((res, rej) => {
    resolve = (value) => {
      isPending = false
      res(value)
    }

    reject = (reason) => {
      isPending = false
      rej(reason)
    }
  })

  return {
    promise,
    resolve,
    reject,
    isPending: () => isPending,
  }
}
